 * @author Michael Isvy
 */
@Entity
@Table(name = "owners")
@EntityListeners(OwnerAuditListener.class)
public class Owner extends Person {
    @Column(name = "address")
    @NotEmpty
    private String address;

    @Column(name = "city")
    @NotEmpty
    private String city;

    @Column(name = "telephone")
    @NotEmpty
    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form, e.g. +61412345678")
    private String telephone;

    @Column(name = "email")
    private String email;

    @Column(name = "postcode")
    private String postcode;

    @Column(name = "registration_date", columnDefinition = "DATE")
    private LocalDate registrationDate;

    @Column(name = "birth_date", columnDefinition = "DATE")
    private LocalDate birthDate;

    @Column(name = "customer_code")
    private String customerCode;

    @Column(name = "namesake_count")
    private Integer namesakeCount;

    @Column(name = "household_member_count")
    private Integer householdMemberCount;

    @Column(name = "possible_duplicate")
    private Boolean possibleDuplicate;

    @Column(name = "possible_duplicate_of")
    private Integer possibleDuplicateOf;

    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
    private Set<Pet> pets;

    /** Default an absent registration date to the server's current date on first persist. */
    @PrePersist
    void defaultRegistrationDate() {
        if (this.registrationDate == null) {
            this.registrationDate = LocalDate.now();
        }
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

    public LocalDate getBirthDate() {
        return this.birthDate;
    }

    public void setBirthDate(LocalDate birthDate) {
        this.birthDate = birthDate;
    }

    public String getCustomerCode() {
        return this.customerCode;
    }

    /** Stable identifier shared by owners of the same household (matching last name and postcode). */
    @Transient
    public String getHouseholdId() {
        return HouseholdId.of(getLastName(), this.postcode);
    }

    public void setCustomerCode(String customerCode) {
        this.customerCode = customerCode;
    }

    /** Derived duplicate-detection key: normalized telephone, email (or empty) and household id
     *  joined with {@code '|'}. Two owners are duplicates only when their whole key matches, so a
     *  shared telephone alone (with matching email) is a collision regardless of household. */
    @Transient
    public String getIdentityKey() {
        return (this.telephone == null ? "" : this.telephone) + "|"
            + (this.email == null ? "" : this.email) + "|";
    }

    /** Membership number formatted {@code <customerCode>-M<YY>}, e.g. {@code SMI-0007-M26}. */
    @Transient
    public String getMembershipNumber() {
        return MembershipNumber.of(this.customerCode, this.registrationDate);
    }

    /** Luhn check digit over the digits of the {@code customerCode}. */
    @Transient
    public Integer getCheckDigit() {
        return CheckDigit.of(this.customerCode);
    }

    public Integer getNamesakeCount() {
        return this.namesakeCount;
    }

    public void setNamesakeCount(Integer namesakeCount) {
        this.namesakeCount = namesakeCount;
    }

    /** Number of members in this owner's household (owners sharing {@link #getHouseholdId()})
     *  captured when the owner was created, including this owner. */
    public Integer getHouseholdMemberCount() {
        return this.householdMemberCount;
    }

    public void setHouseholdMemberCount(Integer householdMemberCount) {
        this.householdMemberCount = householdMemberCount;
    }

    /** True when this owner, at creation, shared an existing owner's last name and postcode
